52	    public record Figures(String name, BigDecimal claimed, BigDecimal dueTotal, BigDecimal overdueTotal,
53	            String grade, boolean retired, List<String> aliases, BigDecimal settled, int overdueCount) {
54	        /** The score: the settled figures over 100, less 5 for each overdue claim, rounded half to
