107	    /** The figures added up, leaving out the single highest and the single lowest when there are
108	     *  three or more. */
109	    static BigDecimal trimmedSum(List<BigDecimal> figures) {
110	        BigDecimal sum = figures.stream().reduce(zero(), BigDecimal::add);
111	        if (figures.size() < 3) {
