149	     *  ancestors' rates from theirs), with {@code on} as its today. */
150	    public Snapshot snapshotAsOf(String sheetId, LocalDate on) {
151	        HistoryService.AsOf then = history.asOf(sheetId, on);
152	        List<Claim> sheetClaims = then.claims().entrySet().stream()
153	                .sorted(Map.Entry.<Long, Claim>comparingByKey().reversed())
154	                .map(Map.Entry::getValue)
155	                .toList();
156	        RateChain.Levels sheetRates = new RateChain.Levels(sheetId, then.rates(),
157	                rateChain.ancestors(sheetId).stream().map(a -> history.asOf(a, on).rates()).toList());
