161	    /** The figures of a sheet with these settings (none: the defaults, today the real date), people
162	     *  (by id, in list order), claims (newest first) and rates. */
163	    private static Snapshot snapshotOf(Optional<Sheet> sheet, Map<Long, Person> sheetPeople, List<Claim> sheetClaims,
164	            RateChain.Levels sheetRates) {
165	        LocalDate today = sheet.map(Sheet::getToday).orElseGet(LocalDate::now);
166	        Function<LocalDate, BigDecimal> floor = floorOf(sheet);
167	        BigDecimal cap = sheet.map(Sheet::getCap).orElse(null);
168	        LateCharge late = LateCharge.of(sheet);
169	        Map<Long, Person> held = new LinkedHashMap<>();
170	        sheetPeople.forEach((id, p) -> {
171	            if (p.isHeld() || p.isRetired()) {
172	                held.put(id, p);
173	            }
174	        });
175	        Function<Claim, RoundingMode> rounding = roundingOf(sheet, sheetClaims);
176	        Map<Long, List<Claim>> counted = new LinkedHashMap<>();
177	        Map<Long, BigDecimal> claimedBy = new LinkedHashMap<>();
178	        for (Claim c : sheetClaims) {
179	            if (counts(c, held, today)) {
180	                counted.computeIfAbsent(c.getPersonId(), id -> new ArrayList<>()).add(c);
181	            }
182	            if (countsClaimed(c, held.get(c.getPersonId()), today) && !isCorrection(c)) {
183	                claimedBy.merge(c.getPersonId(), c.getAmount(), BigDecimal::add);
184	            }
185	        }
186	        Map<Long, Figures> out = new LinkedHashMap<>();
187	        sheetPeople.forEach((id, p) -> {
188	            List<Claim> theirs = counted.getOrDefault(id, List.of());
189	            BigDecimal claimed = zero().add(claimedBy.getOrDefault(id, zero()));
190	            List<Claim> overdueClaims = theirs.stream()
191	                    .filter(c -> c.getStatus().isOpen() && late.isPast(c, p))
192	                    .toList();
193	            BigDecimal overdue = overdueClaims.stream()
194	                    .map(c -> shownDueOf(c, p, sheetRates, floor, late, rounding))
195	                    .filter(Objects::nonNull)
196	                    .reduce(zero(), BigDecimal::add);
197	            BigDecimal settled = theirs.stream()
198	                    .filter(c -> c.getStatus() == ClaimStatus.SETTLED
199	                            && (c.getCorrects() == null || c.getCorrects().isBlank()))
200	                    .map(c -> shownDueOf(c, p, sheetRates, floor, late, rounding))
201	                    .filter(Objects::nonNull)
202	                    .reduce(zero(), BigDecimal::add);
203	            int overdueCount = (int) overdueClaims.stream().filter(c -> !c.isDeferredOn(today)).count();
204	            out.put(id, new Figures(p.getName(), claimed,
205	                    Sheet.capped(dueTotalOf(theirs, p, sheetRates, today, floor, late, rounding), cap), overdue,
206	                    p.gradeOn(today), p.isRetired(), List.copyOf(p.getAliases()), settled, overdueCount));
207	        });
208	        Map<ClaimStatus, Integer> statuses = new LinkedHashMap<>();
209	        sheetClaims.stream().map(Claim::getStatus).filter(Objects::nonNull)
210	                .forEach(st -> statuses.merge(st, 1, Integer::sum));
211	        return new Snapshot(out, statuses);
212	    }
