223	        Map<String, BigDecimal> theirs = snapshot(otherId).dueByGrade();
224	        return GRADES.stream().map(g -> g + " " + mine.getOrDefault(g, zero()).setScale(2).toPlainString() + " "
225	                + theirs.getOrDefault(g, zero()).setScale(2).toPlainString()).toList();
226	    }
