249	    /** The figures of the sheet's descendants (its children, theirs, and so on), each sheet's as
250	     *  it is now, or as it stood at the end of {@code asOf} when given, added up; all zero for a
251	     *  sheet with no children. */
252	    public Consolidated descendants(String sheetId, LocalDate asOf) {
253	        int count = 0;
254	        BigDecimal due = zero();
255	        BigDecimal overdue = zero();
256	        Map<String, BigDecimal> grades = new LinkedHashMap<>();
257	        Map<ClaimStatus, Integer> statuses = new LinkedHashMap<>();
258	        List<Member> members = new ArrayList<>();
259	        Set<String> seen = new HashSet<>(Set.of(sheetId));
260	        ArrayDeque<String> todo = new ArrayDeque<>(List.of(sheetId));
261	        while (!todo.isEmpty()) {
262	            for (Sheet child : sheets.findByParentOrderByIdAsc(todo.poll())) {
263	                if (!seen.add(child.getId())) {
264	                    continue;
265	                }
266	                todo.add(child.getId());
267	                Snapshot figures = asOf == null ? snapshot(child.getId()) : snapshotAsOf(child.getId(), asOf);
268	                count += figures.people().size();
269	                due = due.add(figures.dueTotal());
270	                overdue = overdue.add(figures.overdueTotal());
271	                figures.dueByGrade().forEach((g, d) -> grades.merge(g, d, BigDecimal::add));
272	                figures.statuses().forEach((st, n) -> statuses.merge(st, n, Integer::sum));
273	                members.addAll(figures.members());
274	            }
275	        }
276	        return new Consolidated(count, due, overdue, grades, statuses, members);
277	    }
