279	    /** Each person's due-total for the period from {@code from} to {@code to}, inclusive, by person
280	     *  id, for everyone on the sheet: the dues (n/a ones skipped) their claims due inside it show
281	     *  now, counting each by the status its log gives it at the end of {@code to} (OPEN and SETTLED
282	     *  ones count; one added after then does not; OPEN ones within a hold of their person, unbound,
283	     *  or deferred, left out). */
284	    public Map<Long, BigDecimal> dueByPersonBetween(String sheetId, LocalDate from, LocalDate to) {
285	        Optional<Sheet> sheet = sheets.findById(sheetId);
286	        LocalDate today = sheet.map(Sheet::getToday).orElseGet(LocalDate::now);
287	        Function<LocalDate, BigDecimal> floor = floorOf(sheet);
288	        LateCharge late = LateCharge.of(sheet);
289	        RateChain.Levels sheetRates = rateChain.levels(sheetId);
290	        List<Person> sheetPeople = people.findBySheetIdOrderByPositionAscIdAsc(sheetId);
291	        Map<Long, Person> held = heldPeople(sheetPeople);
292	        Map<Long, Person> byId = sheetPeople.stream().collect(Collectors.toMap(Person::getId, p -> p));
293	        List<Claim> sheetClaims = claims.findBySheetIdOrderByIdDesc(sheetId);
294	        Function<Claim, RoundingMode> rounding = roundingOf(sheet, sheetClaims);
295	        Map<Long, BigDecimal> out = new LinkedHashMap<>();
296	        for (Person p : sheetPeople) {
297	            out.put(p.getId(), zero());
298	        }
299	        Map<Long, ClaimStatus> statusAtEnd = statusesOn(sheetId, to);
300	        sheetClaims.stream()
301	                .filter(c -> countsAt(c, statusAtEnd.containsKey(c.getId()) ? statusAtEnd.get(c.getId()) : c.getStatus(),
302	                        held, today))
303	                .filter(c -> !c.getDueBy().isBefore(from) && !c.getDueBy().isAfter(to))
304	                .filter(c -> byId.containsKey(c.getPersonId()))
305	                .forEach(c -> {
306	                    BigDecimal due = shownDueOf(c, byId.get(c.getPersonId()), sheetRates, floor, late, rounding);
307	                    if (due != null) {
308	                        out.merge(c.getPersonId(), due, BigDecimal::add);
309	                    }
310	                });
311	        return out;
312	    }
