314	    /** Each person's carried figure for the period from {@code from} to {@code to}, by person id,
315	     *  for everyone on the sheet: the dues (n/a ones skipped) their claims show now whose due-by
316	     *  falls in another of the sheet's periods ({@code periodEndOn} gives the to-date of the period
317	     *  containing a date, null outside every one) ending before {@code from}, and that were still
318	     *  OPEN or PENDING at the end of {@code to} by their log, counted as {@link #dueByPersonBetween}
319	     *  counts them. */
320	    public Map<Long, BigDecimal> carriedByPersonInto(String sheetId, LocalDate from, LocalDate to,
321	            Function<LocalDate, LocalDate> periodEndOn) {
322	        Optional<Sheet> sheet = sheets.findById(sheetId);
323	        LocalDate today = sheet.map(Sheet::getToday).orElseGet(LocalDate::now);
324	        Function<LocalDate, BigDecimal> floor = floorOf(sheet);
325	        LateCharge late = LateCharge.of(sheet);
326	        RateChain.Levels sheetRates = rateChain.levels(sheetId);
327	        List<Person> sheetPeople = people.findBySheetIdOrderByPositionAscIdAsc(sheetId);
328	        Map<Long, Person> held = heldPeople(sheetPeople);
329	        Map<Long, Person> byId = sheetPeople.stream().collect(Collectors.toMap(Person::getId, p -> p));
330	        List<Claim> sheetClaims = claims.findBySheetIdOrderByIdDesc(sheetId);
331	        Function<Claim, RoundingMode> rounding = roundingOf(sheet, sheetClaims);
332	        Map<Long, BigDecimal> out = new LinkedHashMap<>();
333	        for (Person p : sheetPeople) {
334	            out.put(p.getId(), zero());
335	        }
336	        Map<Long, ClaimStatus> statusAtEnd = statusesOn(sheetId, to);
337	        sheetClaims.stream()
338	                .filter(c -> byId.containsKey(c.getPersonId()))
339	                .filter(c -> {
340	                    LocalDate ownEnd = periodEndOn.apply(c.getDueBy());
341	                    return ownEnd != null && ownEnd.isBefore(from);
342	                })
343	                .filter(c -> {
344	                    ClaimStatus status = statusAtEnd.containsKey(c.getId()) ? statusAtEnd.get(c.getId()) : c.getStatus();
345	                    return status != null && status.isOpen() && countsAt(c, status, held, today);
346	                })
347	                .forEach(c -> {
348	                    BigDecimal due = shownDueOf(c, byId.get(c.getPersonId()), sheetRates, floor, late, rounding);
349	                    if (due != null) {
350	                        out.merge(c.getPersonId(), due, BigDecimal::add);
351	                    }
352	                });
353	        return out;
354	    }
