361	    /** The statement of a person on a sheet that is not stored (one rebuilt as it stood at the end of
362	     *  a date, its today that date): counting their claims among {@code sheetClaims}, by the rates,
363	     *  floor, late charge and cap of the sheet and the person's holds and retirement, as the live
364	     *  totals do. */
365	    public static Stated statedOn(Sheet sheet, Person person, Long personId, List<Claim> sheetClaims,
366	            RateChain.Levels sheetRates) {
367	        Optional<Sheet> held = Optional.of(sheet);
368	        LocalDate today = sheet.getToday();
369	        Function<LocalDate, BigDecimal> floor = floorOf(held);
370	        LateCharge late = LateCharge.of(held);
371	        Function<Claim, RoundingMode> rounding = roundingOf(held, sheetClaims);
372	        Map<Claim, BigDecimal> counted = new LinkedHashMap<>();
373	        sheetClaims.stream()
374	                .filter(c -> c.getPersonId().equals(personId) && countsFor(c, person, today))
375	                .forEach(c -> counted.put(c, shownDueOf(c, person, sheetRates, floor, late, rounding)));
376	        BigDecimal dueTotal = dueTotalOf(List.copyOf(counted.keySet()), person, sheetRates, today, floor, late, rounding);
377	        return new Stated(counted, Sheet.capped(dueTotal, sheet.getCap()));
