419	    private void recordChanges(String sheetId, String user, Snapshot before, boolean totals) {
420	        Snapshot after = snapshot(sheetId);
421	        after.people().forEach((id, now) -> {
422	            if (!now.sameAs(before.people().get(id))) {
423	                audit.recordOnCommit("ROLLUP sheet=" + sheetId + " by=" + user + " person=" + now.name()
424	                        + " claimed=" + text(now.claimed()) + " due-total=" + text(now.dueTotal()) + " overdue-total=" + text(now.overdueTotal()));
425	            }
426	        });
427	        if (totals || after.claimedTotal().compareTo(before.claimedTotal()) != 0
428	                || after.dueTotal().compareTo(before.dueTotal()) != 0
429	                || after.overdueTotal().compareTo(before.overdueTotal()) != 0) {
430	            audit.recordOnCommit("TOTALS sheet=" + sheetId + " by=" + user + " claimed-total="
431	                    + text(after.claimedTotal()) + " due-total=" + text(after.dueTotal())
432	                    + " overdue-total=" + text(after.overdueTotal()));
433	        }
434	        BigDecimal threshold = sheets.findById(sheetId).map(Sheet::getAlertThreshold).orElse(null);
435	        if (threshold != null) {
436	            after.people().forEach((id, now) -> {
437	                Figures was = before.people().get(id);
438	                if (above(now.dueTotal(), threshold) && (was == null || !above(was.dueTotal(), threshold))) {
439	                    audit.recordOnCommit("ALERT sheet=" + sheetId + " by=" + user + " name=" + now.name()
440	                            + " due-total=" + text(now.dueTotal()));
441	                }
442	            });
443	        }
444	    }
