446	    /** Whether a due-total (null: n/a) is above the alert threshold. */
447	    private static boolean above(BigDecimal dueTotal, BigDecimal threshold) {
448	        return dueTotal != null && dueTotal.compareTo(threshold) > 0;
449	    }
