457	    /** Whether a claim counts toward due totals: only OPEN (or PENDING) and SETTLED ones
458	     *  do, but not (unless bound by a statement) any open one of a person (by id in {@code held})
459	     *  whose retirement date the sheet's
460	     *  today has reached, nor one deferred on the sheet's today. */
461	    private static boolean counts(Claim c, Map<Long, Person> held, LocalDate today) {
462	        return countsFor(c, held.get(c.getPersonId()), today);
463	    }
464	
465	    /** Whether a claim of the person (null: one with neither a hold nor a retirement) counts, as
466	     *  {@link #counts} has it. */
467	    private static boolean countsFor(Claim c, Person person, LocalDate today) {
468	        if (c.getStatus() == ClaimStatus.SETTLED) {
469	            return true;
470	        }
471	        if (!c.getStatus().isOpen() || c.isDeferredOn(today)) {
472	            return false;
473	        }
474	        return c.isBound() || !leftOut(person, c, today);
475	    }
476	
477	    /** Whether a claim counts toward claimed: as {@link #countsFor} has it. */
478	    private static boolean countsClaimed(Claim c, Person person, LocalDate today) {
479	        if (c.getStatus() == ClaimStatus.SETTLED) {
480	            return true;
481	        }
482	        if (!c.getStatus().isOpen() || c.isDeferredOn(today)) {
483	            return false;
484	        }
485	        return c.isBound() || person == null || !person.retiredOn(today);
486	    }
