488	    /** Whether a claim counts toward a period's due-total, taken in {@code status} (the one it had
489	     *  at the period's end; null when it was not yet added then): as {@link #counts} has it. */
490	    private static boolean countsAt(Claim c, ClaimStatus status, Map<Long, Person> held, LocalDate today) {
491	        if (status == null) {
492	            return false;
493	        }
494	        if (status == ClaimStatus.SETTLED) {
495	            return true;
496	        }
497	        if (!status.isOpen() || c.isDeferredOn(today)) {
498	            return false;
499	        }
500	        // a reached retirement leaves out a claim still open now, as the live due-total does
501	        return !c.getStatus().isOpen() || c.isBound() || !leftOut(held.get(c.getPersonId()), c, today);
502	    }
