504	    /** The status each of the sheet's claims had at the end of {@code on}, by claim id, as their
505	     *  status logs record it (null for a claim not yet added then); a claim with no log at all is
506	     *  left out, taken in its status now. */
507	    private Map<Long, ClaimStatus> statusesOn(String sheetId, LocalDate on) {
508	        Map<Long, ClaimStatus> out = new LinkedHashMap<>();
509	        for (ClaimLog line : log.findBySheetIdOrderByIdAsc(sheetId)) {
510	            ClaimStatus before = out.get(line.getClaimId());
511	            out.put(line.getClaimId(), line.getOn().isAfter(on) ? before : line.getStatus());
512	        }
513	        return out;
514	    }
