516	    /** Whether an unbound open claim of the person (null: one with neither a hold nor a retirement)
517	     *  is left out of the live totals: their retirement date reached on the sheet's today. A hold
518	     *  (the claim's or its person's) leaves nothing out; it only takes the person out of pool cuts. */
519	    private static boolean leftOut(Person person, Claim c, LocalDate today) {
520	        return person != null && person.retiredOn(today);
521	    }
