523	    /** The people with a hold or a retirement date, by id. */
524	    private static Map<Long, Person> heldPeople(List<Person> sheetPeople) {
525	        return sheetPeople.stream().filter(p -> p.isHeld() || p.isRetired()).collect(Collectors.toMap(Person::getId, p -> p));
526	    }
