528	    /** A person's due-total: the sum of the dues their counting claims show (n/a ones skipped);
529	     *  null (n/a) when their grade in force on the sheet's today has no rate then, unless a claim
530	     *  shows a due (a fixed or bound one, or one at the rate of the grade they had on its date). */
531	    private static BigDecimal dueTotalOf(List<Claim> counted, Person person, RateChain.Levels sheetRates, LocalDate today,
532	            Function<LocalDate, BigDecimal> floor, LateCharge late, Function<Claim, RoundingMode> rounding) {
533	        List<BigDecimal> dues = counted.stream()
534	                .map(c -> shownDueOf(c, person, sheetRates, floor, late, rounding))
535	                .filter(Objects::nonNull)
536	                .toList();
537	        if (inForce(person, sheetRates.inForce(), today).isEmpty() && dues.isEmpty()) {
538	            return null;
539	        }
540	        return dues.stream().reduce(zero(), BigDecimal::add);
541	    }
542	
543	    /** The due a claim shows: the due fixed when it was settled, else the one a statement bound it
544	     *  to (null: n/a), late charge included, else its amount times the rate in force on its date of its person's grade
545	     *  then (as the claim applies the rates: not a forward-only one saved after it was added), rounded as its rounding policy has it, raised to the sheet's floor in force on its date (a
546	     *  correction's never is), with the late charge worked out on that floored figure on top. */
547	    private static BigDecimal shownDueOf(Claim c, Person person, RateChain.Levels sheetRates, Function<LocalDate, BigDecimal> floor,
548	            LateCharge late, Function<Claim, RoundingMode> rounding) {
549	        if (c.getSettledDue() != null) {
550	            return c.getSettledDue();
551	        }
552	        if (c.isBound()) {
553	            return c.getStatedDue();
554	        }
555	        RoundingMode mode = rounding.apply(c);
556	        BigDecimal figure = figureOf(c, person, sheetRates, mode);
557	        BigDecimal floored = figure == null || c.isCorrection() ? figure : figure.max(floor.apply(c.getDate()));
558	        return late.addTo(c, person, floored, mode);
559	    }
560	
561	    /** A claim's rate figure before any late charge or floor. */
562	    private static BigDecimal figureOf(Claim c, Person person, RateChain.Levels sheetRates, RoundingMode mode) {
563	        return inForce(person, sheetRates.forClaim(c.getAdded()), c.getDate())
564	                .map(r -> c.getAmount().multiply(r.getPct()).divide(BigDecimal.valueOf(100), 2, mode))
565	                .orElse(null);
566	    }
567	
568	    /** How each claim's live figures round: by the sheet's policy date against its date, or for a
569	     *  correction the date of the claim (of the same person) it corrects. */
570	    private static Function<Claim, RoundingMode> roundingOf(Optional<Sheet> sheet, List<Claim> sheetClaims) {
571	        Rounding rounding = Rounding.of(sheet);
572	        Map<String, LocalDate> numbered = new LinkedHashMap<>();
573	        for (Claim c : sheetClaims) {
574	            if (c.getNumber() != null) {
575	                numbered.putIfAbsent(c.getPersonId() + "/" + c.getNumber(), c.getDate());
576	            }
577	        }
578	        return c -> rounding.on(c.getCorrects() == null ? c.getDate()
579	                : numbered.getOrDefault(c.getPersonId() + "/" + c.getCorrects(), c.getDate()));
580	    }
581	
582	    /** The rate in force on a date for the person's grade in force then; none when that one's
583	     *  to-date has passed by then. */
584	    private static Optional<Rate> inForce(Person person, List<Rate> sheetRates, LocalDate on) {
585	        String grade = person.gradeOn(on);
586	        return sheetRates.stream()
587	                .filter(r -> r.getGrade().equals(grade) && r.appliesOn(on))
588	                .max(Comparator.comparing(Rate::getFrom, Comparator.nullsFirst(Comparator.naturalOrder())))
589	                .filter(r -> r.runsThrough(on));
590	    }
591	
592	    /** The sheet's floor in force on each date. */
593	    private static Function<LocalDate, BigDecimal> floorOf(Optional<Sheet> sheet) {
594	        return on -> sheet.map(s -> s.floorOn(on)).orElse(Sheet.DEFAULT_FLOOR);
595	    }
596	
597	    private static BigDecimal zero() {
598	        return BigDecimal.ZERO.setScale(2);
599	    }
600	
601	    /** A figure as the screen shows it: two decimals, or n/a. */
602	    public static String text(BigDecimal value) {
603	        return value == null ? "n/a" : value.setScale(2).toPlainString();
604	    }
605	
606	    /** Whether a claim corrects another: claimed leaves such claims out. */
607	    private static boolean isCorrection(Claim c) {
608	        return c.getCorrects() != null && !c.getCorrects().isBlank();
609	    }
610	}
